ALTER TABLE products ADD COLUMN keywords TEXT NOT NULL DEFAULT '';
CREATE VIRTUAL TABLE product_search USING fts5(product_id UNINDEXED,title,terms,body,department,tokenize='unicode61 remove_diacritics 2',prefix='2 3');
INSERT INTO product_search(product_id,title,terms,body,department) SELECT products.id,lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(products.name,'أ','ا'),'إ','ا'),'آ','ا'),'ٱ','ا'),'ى','ي'),'ی','ي'),'ة','ه'),'ـ',''),'ً',''),'ٌ',''),'ٍ',''),'َ',''),'ُ',''),'ِ',''),'ّ',''),'ْ',''),'ٰ','')),lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace((products.keywords||' '||products.sku),'أ','ا'),'إ','ا'),'آ','ا'),'ٱ','ا'),'ى','ي'),'ی','ي'),'ة','ه'),'ـ',''),'ً',''),'ٌ',''),'ٍ',''),'َ',''),'ُ',''),'ِ',''),'ّ',''),'ْ',''),'ٰ','')),lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(products.description,'أ','ا'),'إ','ا'),'آ','ا'),'ٱ','ا'),'ى','ي'),'ی','ي'),'ة','ه'),'ـ',''),'ً',''),'ٌ',''),'ٍ',''),'َ',''),'ُ',''),'ِ',''),'ّ',''),'ْ',''),'ٰ','')),lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(COALESCE((SELECT CASE WHEN active=1 THEN name ELSE '' END FROM categories WHERE id=products.category_id),''),'أ','ا'),'إ','ا'),'آ','ا'),'ٱ','ا'),'ى','ي'),'ی','ي'),'ة','ه'),'ـ',''),'ً',''),'ٌ',''),'ٍ',''),'َ',''),'ُ',''),'ِ',''),'ّ',''),'ْ',''),'ٰ','')) FROM products;
CREATE TRIGGER product_search_insert AFTER INSERT ON products BEGIN INSERT INTO product_search(product_id,title,terms,body,department) VALUES(NEW.id,lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(NEW.name,'أ','ا'),'إ','ا'),'آ','ا'),'ٱ','ا'),'ى','ي'),'ی','ي'),'ة','ه'),'ـ',''),'ً',''),'ٌ',''),'ٍ',''),'َ',''),'ُ',''),'ِ',''),'ّ',''),'ْ',''),'ٰ','')),lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace((NEW.keywords||' '||NEW.sku),'أ','ا'),'إ','ا'),'آ','ا'),'ٱ','ا'),'ى','ي'),'ی','ي'),'ة','ه'),'ـ',''),'ً',''),'ٌ',''),'ٍ',''),'َ',''),'ُ',''),'ِ',''),'ّ',''),'ْ',''),'ٰ','')),lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(NEW.description,'أ','ا'),'إ','ا'),'آ','ا'),'ٱ','ا'),'ى','ي'),'ی','ي'),'ة','ه'),'ـ',''),'ً',''),'ٌ',''),'ٍ',''),'َ',''),'ُ',''),'ِ',''),'ّ',''),'ْ',''),'ٰ','')),lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(COALESCE((SELECT CASE WHEN active=1 THEN name ELSE '' END FROM categories WHERE id=NEW.category_id),''),'أ','ا'),'إ','ا'),'آ','ا'),'ٱ','ا'),'ى','ي'),'ی','ي'),'ة','ه'),'ـ',''),'ً',''),'ٌ',''),'ٍ',''),'َ',''),'ُ',''),'ِ',''),'ّ',''),'ْ',''),'ٰ',''))); END;
CREATE TRIGGER product_search_update AFTER UPDATE OF name,sku,keywords,description,category_id ON products BEGIN DELETE FROM product_search WHERE product_id=OLD.id; INSERT INTO product_search(product_id,title,terms,body,department) VALUES(NEW.id,lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(NEW.name,'أ','ا'),'إ','ا'),'آ','ا'),'ٱ','ا'),'ى','ي'),'ی','ي'),'ة','ه'),'ـ',''),'ً',''),'ٌ',''),'ٍ',''),'َ',''),'ُ',''),'ِ',''),'ّ',''),'ْ',''),'ٰ','')),lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace((NEW.keywords||' '||NEW.sku),'أ','ا'),'إ','ا'),'آ','ا'),'ٱ','ا'),'ى','ي'),'ی','ي'),'ة','ه'),'ـ',''),'ً',''),'ٌ',''),'ٍ',''),'َ',''),'ُ',''),'ِ',''),'ّ',''),'ْ',''),'ٰ','')),lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(NEW.description,'أ','ا'),'إ','ا'),'آ','ا'),'ٱ','ا'),'ى','ي'),'ی','ي'),'ة','ه'),'ـ',''),'ً',''),'ٌ',''),'ٍ',''),'َ',''),'ُ',''),'ِ',''),'ّ',''),'ْ',''),'ٰ','')),lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(COALESCE((SELECT CASE WHEN active=1 THEN name ELSE '' END FROM categories WHERE id=NEW.category_id),''),'أ','ا'),'إ','ا'),'آ','ا'),'ٱ','ا'),'ى','ي'),'ی','ي'),'ة','ه'),'ـ',''),'ً',''),'ٌ',''),'ٍ',''),'َ',''),'ُ',''),'ِ',''),'ّ',''),'ْ',''),'ٰ',''))); END;
CREATE TRIGGER product_search_delete AFTER DELETE ON products BEGIN DELETE FROM product_search WHERE product_id=OLD.id; END;
CREATE TRIGGER category_search_update AFTER UPDATE OF name,active ON categories BEGIN UPDATE product_search SET department=lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(CASE WHEN NEW.active=1 THEN NEW.name ELSE '' END,'أ','ا'),'إ','ا'),'آ','ا'),'ٱ','ا'),'ى','ي'),'ی','ي'),'ة','ه'),'ـ',''),'ً',''),'ٌ',''),'ٍ',''),'َ',''),'ُ',''),'ِ',''),'ّ',''),'ْ',''),'ٰ','')) WHERE product_id IN (SELECT id FROM products WHERE category_id=NEW.id); END;
CREATE TRIGGER category_search_delete AFTER DELETE ON categories BEGIN UPDATE product_search SET department='' WHERE product_id IN (SELECT id FROM products WHERE category_id=OLD.id); END;
